package com.bank.capdeploy.service;

import java.util.Arrays;
import java.util.Comparator;
import java.util.logging.Logger;

// Fractional Knapsack: greedy by value-to-weight (return-per-capital) ratio.
public class CapitalDeploymentService {
    private static final Logger log = Logger.getLogger(CapitalDeploymentService.class.getName());

    public double maxReturn(int[] weights, int[] values, int capital) {
        int n = weights.length;
        double[][] items = new double[n][3];               // {weight, value, ratio}
        for (int i = 0; i < n; i++) {
            items[i][0] = weights[i];
            items[i][1] = values[i];
            items[i][2] = (double) values[i] / weights[i]; // return per unit of capital
        }
        Arrays.sort(items, Comparator.comparingDouble((double[] a) -> a[2]).reversed());
        double remaining = capital, total = 0.0;
        for (double[] it : items) {
            if (remaining >= it[0]) {                      // fund this investment fully
                remaining -= it[0];
                total += it[1];
            } else {                                       // fund the fraction that fits
                total += it[1] * (remaining / it[0]);
                break;                                     // capital exhausted
            }
        }
        final double result = total;
        log.info(() -> "Maximum return from deployed capital = " + result);
        return total;
    }
}
