package com.bank.capdeploy;

import com.bank.capdeploy.service.CapitalDeploymentService;
import java.util.logging.Logger;

public class CapitalDeploymentApplication {
    private static final Logger log = Logger.getLogger(CapitalDeploymentApplication.class.getName());

    public static void main(String[] args) {
        CapitalDeploymentService service = new CapitalDeploymentService();
        int[] capitalNeeded = {10, 20, 30};                // capital each investment needs
        int[] expectedReturn = {60, 100, 120};             // expected return
        double best = service.maxReturn(capitalNeeded, expectedReturn, 50); // capital = 50
        log.info(() -> "Final maximum return = " + best);
    }
}
